int check_pmd_entry(pmd_t *pmd) {
    pmd_t pmd_val;

    /* Atomically read the PMD value to ensure consistency during checks. */
    pmd_val = *pmd;

    /* Prevent compiler reordering to ensure the value is not changed during checks. */
    __asm__ __volatile__ ("": : : "memory");

    /* Check if the PMD is none, a transparent huge page, or marked as bad. */
    if (pmd_none(pmd_val) || pmd_trans_huge(pmd_val) || pmd_bad(pmd_val)) {
        /* If the PMD is marked as bad, perform applicable bad-entry handling. */
        if (pmd_bad(pmd_val)) {
            handle_bad_pmd(pmd_val);
        }
        return 1;
    }

    return 0;
}
